import React from "react";
import "./AchievementCard.scss";

export default function AchievementCard({cardInfo, isDark, index}) {
  function renderAuthors(authors) {
    return authors.split("Yuxin Shen").map((part, authorIndex, parts) => (
      <React.Fragment key={`${part}-${authorIndex}`}>
        {part}
        {authorIndex < parts.length - 1 && <strong>Yuxin Shen</strong>}
      </React.Fragment>
    ));
  }

  return (
    <article
      className={`${isDark ? "dark-mode " : ""}certificate-card${
        cardInfo.image ? " has-teaser" : ""
      }`}
    >
      {cardInfo.image && (
        <div className="publication-teaser">
          <img
            src={cardInfo.image}
            alt={cardInfo.imageAlt || `${cardInfo.title} teaser`}
            style={{objectFit: cardInfo.imageFit || "cover"}}
          />
          <span aria-hidden="true">{String(index + 1).padStart(2, "0")}</span>
        </div>
      )}
      <div className="certificate-detail-div">
        <h5 className={isDark ? "dark-mode card-title" : "card-title"}>
          {cardInfo.title}
        </h5>
        <p className={isDark ? "card-dark-subtitle" : "card-subtitle"}>
          {cardInfo.description}
          {cardInfo.ccfRank && (
            <span
              className={`ccf-badge ccf-${cardInfo.ccfRank.toLowerCase()}`}
              aria-label={`CCF ${cardInfo.ccfRank} class`}
            >
              CCF {cardInfo.ccfRank}
            </span>
          )}
        </p>
        {cardInfo.award && (
          <p className="publication-award">{cardInfo.award}</p>
        )}
        <p className={isDark ? "dark-mode card-authors" : "card-authors"}>
          {renderAuthors(cardInfo.authors)}
        </p>
      </div>
      {cardInfo.footer.length > 0 && (
        <div className="certificate-card-footer">
          {cardInfo.footer.map((v, i) => {
            return (
              <a
                key={i}
                className={
                  isDark ? "dark-mode certificate-tag" : "certificate-tag"
                }
                href={v.url}
                target="_blank"
                rel="noopener noreferrer"
                aria-label={`${v.name}: ${cardInfo.title}`}
              >
                {v.name}
                <span aria-hidden="true">↗</span>
              </a>
            );
          })}
        </div>
      )}
    </article>
  );
}
